package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.ClientCredentialsTokenTtlSecondsVO;

class ClientCredentialsTokenTtlSecondsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of client credentials token ttl seconds of oauth client")
  void test_client_credentials_token_ttl_seconds_value_holder_assign_plain_value() {
    Object holder = new Object();
    ClientCredentialsTokenTtlSecondsValueHolder<Object> value =
        new ClientCredentialsTokenTtlSecondsValueHolder<>(holder);
    Assertions.assertSame(holder, value.clientCredentialsTokenTtlSeconds(1),
        "Setters must return the holder");
    Assertions.assertTrue(value.getClientCredentialsTokenTtlSecondsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getClientCredentialsTokenTtlSeconds().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of client credentials token ttl seconds of oauth client")
  void test_client_credentials_token_ttl_seconds_value_holder_assign_value_object() {
    Object holder = new Object();
    ClientCredentialsTokenTtlSecondsValueHolder<Object> value =
        new ClientCredentialsTokenTtlSecondsValueHolder<>(holder);
    ClientCredentialsTokenTtlSecondsVO vo = ClientCredentialsTokenTtlSecondsVO.from(1);
    Assertions.assertFalse(value.getClientCredentialsTokenTtlSecondsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.clientCredentialsTokenTtlSeconds(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getClientCredentialsTokenTtlSecondsValue().orElseThrow());
    Assertions.assertSame(holder, value.clientCredentialsTokenTtlSeconds(Optional.empty()));
    Assertions.assertFalse(value.getClientCredentialsTokenTtlSecondsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.clientCredentialsTokenTtlSeconds(Optional.of(vo)));
    Assertions.assertSame(vo, value.getClientCredentialsTokenTtlSecondsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of client credentials token ttl seconds of oauth client against the original")
  void test_client_credentials_token_ttl_seconds_value_holder_read() {
    Object holder = new Object();
    ClientCredentialsTokenTtlSecondsValueHolder<Object> value =
        new ClientCredentialsTokenTtlSecondsValueHolder<>(holder);
    ClientCredentialsTokenTtlSecondsVO vo = ClientCredentialsTokenTtlSecondsVO.from(1);
    ClientCredentialsTokenTtlSecondsVO other = ClientCredentialsTokenTtlSecondsVO.from(1);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getClientCredentialsTokenTtlSecondsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readClientCredentialsTokenTtlSeconds(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readClientCredentialsTokenTtlSeconds(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.clientCredentialsTokenTtlSeconds(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo,
        value.readClientCredentialsTokenTtlSeconds(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readClientCredentialsTokenTtlSeconds(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of client credentials token ttl seconds of oauth client")
  void test_client_credentials_token_ttl_seconds_value_holder_unset() {
    Object holder = new Object();
    ClientCredentialsTokenTtlSecondsValueHolder<Object> value =
        new ClientCredentialsTokenTtlSecondsValueHolder<>(holder);
    ClientCredentialsTokenTtlSecondsVO vo = ClientCredentialsTokenTtlSecondsVO.from(1);
    value.clientCredentialsTokenTtlSeconds(vo);
    Assertions.assertSame(holder, value
        .unsetClientCredentialsTokenTtlSecondsIfMatches("clientCredentialsTokenTtlSeconds_other"));
    Assertions.assertTrue(value.getClientCredentialsTokenTtlSecondsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetClientCredentialsTokenTtlSecondsIfMatches("clientCredentialsTokenTtlSeconds"));
    Assertions.assertFalse(value.getClientCredentialsTokenTtlSecondsValue().isPresent(),
        "The field name must clear the value");
    value.clientCredentialsTokenTtlSeconds(vo);
    Assertions.assertSame(holder, value.unsetClientCredentialsTokenTtlSeconds());
    Assertions.assertFalse(value.getClientCredentialsTokenTtlSecondsValue().isPresent(),
        "Unset must clear the value");
  }
}
